svg.script:
(function () {
  "use strict";

  // ===================== TIMELINE CONSTANTS =====================
  var DURATION = 6000;      // total loop duration, ms
  var STEP_PERIOD = 800;    // one leg-swing cycle, ms
  var TAIL_PERIOD = 900;    // tail wag cycle, ms
  var X_START = 650;
  var X_END = -850;
  var TRACK_X = 110;
  var TRACK_W = 1050;

  // ===================== STATE =====================
  var currentTime = 0;      // ms, always within [0, DURATION)
  var playing = false;
  var rafId = null;
  var lastTs = null;

  function byId(id) { return document.getElementById(id); }

  function setTransform(id, str) {
    var node = byId(id);
    if (node) node.setAttribute('transform', str);
  }

  // Pure function of time -> full character pose.
  // Same t always yields the same pose, so seeking never needs to "replay".
  function render(t) {
    currentTime = t;

    var phase = (t % STEP_PERIOD) / STEP_PERIOD * 2 * Math.PI;
    var legSwing = 18 * Math.sin(phase);
    var armSwing = 20 * Math.sin(phase);
    var bob = 5 * Math.abs(Math.sin(phase));

    var tailPhase = (t % TAIL_PERIOD) / TAIL_PERIOD * 2 * Math.PI;
    var tailWag = 12 * Math.sin(tailPhase);

    var progress = DURATION > 0 ? (t / DURATION) : 0;
    var xOffset = X_START + (X_END - X_START) * progress;

    setTransform('walkMotionGroup', 'translate(' + xOffset.toFixed(2) + ',0)');
    setTransform('leftUpperLeg', 'translate(-30,25) rotate(' + (2 + legSwing).toFixed(2) + ')');
    setTransform('rightUpperLeg', 'translate(30,25) rotate(' + (-2 - legSwing).toFixed(2) + ')');
    setTransform('leftUpperArm', 'rotate(' + (8 - armSwing).toFixed(2) + ')');
    setTransform('rightUpperArm', 'rotate(' + (-8 + armSwing).toFixed(2) + ')');
    setTransform('tail', 'translate(-45,30) rotate(' + (15 + tailWag).toFixed(2) + ')');
    setTransform('torso', 'translate(0,' + (-20 - bob).toFixed(2) + ')');

    updateUI(progress);
  }

  function updateUI(progress) {
    var fill = byId('seekFill');
    var handle = byId('seekHandle');
    if (fill) fill.setAttribute('width', Math.max(0, TRACK_W * progress).toFixed(2));
    if (handle) handle.setAttribute('cx', (TRACK_X + TRACK_W * progress).toFixed(2));
    var label = byId('playPauseLabel');
    if (label) label.textContent = playing ? 'Pause' : 'Play';
  }

  function loop(now) {
    if (!playing) return;
    if (lastTs === null) lastTs = now;
    var dt = now - lastTs;
    lastTs = now;
    var t = (currentTime + dt) % DURATION;
    render(t);
    rafId = window.requestAnimationFrame(loop);
  }

  // ===================== PUBLIC API =====================
  function play() {
    if (playing) return;
    playing = true;
    lastTs = null;
    rafId = window.requestAnimationFrame(loop);
  }

  function pause() {
    playing = false;
    if (rafId !== null) {
      window.cancelAnimationFrame(rafId);
      rafId = null;
    }
    render(currentTime);
  }

  function resume() {
    play();
  }

  function seek(progress) {
    progress = Math.min(1, Math.max(0, progress));
    render(progress * DURATION);
  }

  function setTime(ms) {
    ms = Math.min(DURATION, Math.max(0, ms));
    render(ms);
  }

  function getTime() { return currentTime; }
  function getDuration() { return DURATION; }
  function isPlaying() { return playing; }

  window.CharacterPlayer = {
    play: play,
    pause: pause,
    resume: resume,
    seek: seek,
    setTime: setTime,
    getTime: getTime,
    getDuration: getDuration,
    isPlaying: isPlaying
  };

  // ===================== BUILT-IN UI (optional convenience) =====================
  function attachUI() {
    var svgRoot = document.getElementById('sceneRoot') || document.documentElement;

    function toggle() {
      if (isPlaying()) { pause(); } else { resume(); }
    }

    var btn = byId('playPauseBtn');
    var label = byId('playPauseLabel');
    if (btn) btn.addEventListener('pointerdown', toggle);
    if (label) label.addEventListener('pointerdown', toggle);

    var dragging = false;

    function seekFromClientX(clientX) {
      var pt = svgRoot.createSVGPoint();
      pt.x = clientX;
      pt.y = 0;
      var ctm = svgRoot.getScreenCTM();
      if (!ctm) return;
      var loc = pt.matrixTransform(ctm.inverse());
      var progress = (loc.x - TRACK_X) / TRACK_W;
      seek(progress);
    }

    var track = byId('seekTrack');
    var handle = byId('seekHandle');
    if (track) {
      track.addEventListener('pointerdown', function (e) {
        dragging = true;
        seekFromClientX(e.clientX);
      });
    }
    if (handle) {
      handle.addEventListener('pointerdown', function (e) {
        dragging = true;
        e.stopPropagation();
      });
    }
    window.addEventListener('pointermove', function (e) {
      if (dragging) seekFromClientX(e.clientX);
    });
    window.addEventListener('pointerup', function () { dragging = false; });
  }

  attachUI();
  render(0);
  play();
})();
